import Foundation
import BackgroundTasks
import UserNotifications

class BackgroundTaskScheduler {
    static let shared = BackgroundTaskScheduler()
    private let logger = Logging.shared

    // Task identifiers
    private let dailyVerificationTaskId = "com.dailydrop.verification"
    private let refreshTaskId = "com.dailydrop.refresh"

    init() {}

    func registerBackgroundTasks() {
        BGTaskScheduler.shared.register(
            forTaskWithIdentifier: dailyVerificationTaskId,
            using: nil
        ) { [weak self] task in
            self?.handleDailyVerification(task: task)
        }

        BGTaskScheduler.shared.register(
            forTaskWithIdentifier: refreshTaskId,
            using: nil
        ) { [weak self] task in
            self?.handleAppRefresh(task: task)
        }

        logger.info("Registered background tasks")
    }

    func scheduleVerificationTask() {
        let request = BGProcessingTaskRequest(identifier: dailyVerificationTaskId)

        // Schedule for 3 AM
        var components = DateComponents()
        components.hour = 3
        components.minute = 0

        if let nextRun = Calendar.current.nextDate(
            after: Date(),
            matching: components,
            matchingPolicy: .nextTime
        ) {
            request.earliestBeginDate = nextRun
        }

        request.requiresNetworkConnectivity = true
        request.requiresExternalPower = false

        do {
            try BGTaskScheduler.shared.submit(request)
            logger.info("Scheduled daily verification task")
        } catch {
            logger.error("Failed to schedule verification task: \(error)")
        }
    }

    func scheduleAppRefresh() {
        let request = BGAppRefreshTaskRequest(identifier: refreshTaskId)
        request.earliestBeginDate = Date(timeIntervalSinceNow: 3600) // 1 hour

        do {
            try BGTaskScheduler.shared.submit(request)
            logger.info("Scheduled app refresh")
        } catch {
            logger.error("Failed to schedule app refresh: \(error)")
        }
    }

