import Foundation

// Points-only manager for gamification
final class PaymentsManager: NSObject, ObservableObject {
    @Published var userPoints: Int = 0

    private let localDataManager = LocalDataManager.shared

    override init() {
        super.init()
        loadUserPoints()
    }

    private func loadUserPoints() {
        if let profile = localDataManager.fetchUserProfile() {
            userPoints = Int(profile.pointsBalance)
        }
    }

    // MARK: - Points Management (No Real Money)

    func awardPoints(amount: Int) {
        userPoints += amount
        if let profile = localDataManager.fetchUserProfile() {
            profile.pointsBalance = Int32(userPoints)
            localDataManager.createOrUpdateUserProfile()
        }
    }

    func deductPoints(amount: Int) {
        userPoints = max(0, userPoints - amount)
        if let profile = localDataManager.fetchUserProfile() {
            profile.pointsBalance = Int32(userPoints)
            localDataManager.createOrUpdateUserProfile()
        }
    }

