    // MARK: - Habit Operations (Local Only)

    func activateHabit(userId: String, habitType: String, dailyAmountCents: Int, userEmail: String? = nil) async throws -> HabitActivationResponse {
        // Create or update habit locally
        if let type = HabitType(rawValue: habitType) {
            let habit = localDataManager.createHabit(type: type, isActive: true, stakePoints: Int32(dailyAmountCents / 100))

            return HabitActivationResponse(
                success: true,
                habitId: Int(habit.id.hashValue),
                message: "Habit activated locally"
            )
        }

