import Foundation

struct Habit: Identifiable, Codable, Equatable {
    let id: UUID
    let type: HabitType
    var isActive: Bool
    var dailyStakeDrops: Int // 10-200 drops per habit
    var customThreshold: Double?
    var configuration: HabitConfiguration?
    var lastModified: Date
    var toggleHistory: [HabitToggleEvent]
    var databaseId: Int? // Backend database ID for 24-hour tracking

    init(
        id: UUID = UUID(),
        type: HabitType,
        isActive: Bool = false,
        dailyStakeDrops: Int = 50, // 50 drops default
        customThreshold: Double? = nil,
        configuration: HabitConfiguration? = nil,
        databaseId: Int? = nil
    ) {
        self.id = id
        self.type = type
        self.isActive = isActive
        self.dailyStakeDrops = dailyStakeDrops
        self.customThreshold = customThreshold
        self.configuration = configuration
        self.lastModified = Date()
        self.toggleHistory = []
        self.databaseId = databaseId
    }

    var threshold: Double {
        customThreshold ?? type.defaultThreshold
    }

    var dailyStakeDropsDisplay: Int {
        dailyStakeDrops
    }

    mutating func updateStake(_ newDrops: Int) {
        // Validate stake amount (10-200 drops)
        guard newDrops >= 10 && newDrops <= 200 else {
            Logging.shared.warning("Invalid stake amount: \(newDrops) drops", category: "validation")
            return
        }

        dailyStakeDrops = newDrops
        lastModified = Date()
    }

    mutating func toggle(at date: Date = Date()) {
        isActive.toggle()
        lastModified = date
        toggleHistory.append(HabitToggleEvent(
            timestamp: date,
            wasActivated: isActive
        ))
    }

    func canToggleAt(_ date: Date, dailyCutoffTime: Date) -> Bool {
        // Rate limit: no toggles within 15 minutes of cutoff
        let cutoffBuffer = 15.0 * 60.0 // 15 minutes in seconds
        let timeUntilCutoff = dailyCutoffTime.timeIntervalSince(date)

        if timeUntilCutoff > 0 && timeUntilCutoff < cutoffBuffer {
            return false
        }

        // Check recent toggle history (no more than 3 toggles in last hour)
        let oneHourAgo = date.addingTimeInterval(-3600)
        let recentToggles = toggleHistory.filter { $0.timestamp > oneHourAgo }

        return recentToggles.count < 3
    }
}

